package app.lensdrop.transfer;

import android.app.*;import android.content.*;import android.graphics.*;import android.media.ExifInterface;import android.net.Uri;import android.os.*;import android.widget.*;import org.json.*;
import java.io.*;import java.security.*;import java.util.*;import java.util.concurrent.*;

/** A separate, explicitly selected JPEG print queue. It never publishes a guest photo automatically. */
public final class PrintActivity extends Activity {
    private Config config;private TextView info,jobs;private Spinner route;private final ExecutorService io=Executors.newSingleThreadExecutor();private final Handler handler=new Handler(Looper.getMainLooper());
    private final Runnable refresh=new Runnable(){public void run(){if(io.isShutdown())return;io.execute(()->{try(PrintQueue q=new PrintQueue(PrintActivity.this);QueueDb photos=new QueueDb(PrintActivity.this)){StringBuilder text=new StringBuilder();JSONArray a=q.list();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i),j=new JSONObject(r.getString("spec"));text.append(r.getString("id").substring(0,8)).append(" / ").append(j.getInt("copies")).append(PrintProfilePolicy.isPair(j.optString("profile_id"))?" sheet copies (2 strips each) / ":" copies / ").append(r.getString("state")).append(" / ").append(r.optString("remote_state")).append("\n").append(r.optString("error")).append("\n");String archiveId=r.optString("archive_job_id");if(!archiveId.isEmpty())try(android.database.Cursor c=photos.getReadableDatabase().rawQuery("SELECT state,delivery_synced,delivery_id FROM jobs WHERE id=?",new String[]{archiveId})){if(c.moveToFirst())text.append("Cloud photo: ").append(c.getString(0)).append(c.getString(2)==null?" / staff-only":c.getInt(1)==1?" / guest linked":" / guest link pending/review").append("\n");}text.append("\n");}runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())jobs.setText(text.length()>0?text.toString():"No print jobs.");});}catch(Exception ignored){}});info.setText(config.get("print_status"));handler.postDelayed(this,5000);}};
    @Override public void onCreate(Bundle state){super.onCreate(state);config=new Config(this);
        LinearLayout page=LuceUi.screen(this,"Print a photo","A confirmed print also keeps its private cloud-archive task.\n"+LuceUi.version(this),true);
        info=LuceUi.notice(this,page,config.get("print_status").isEmpty()?"Prepare your assigned station first. No paper is used until you confirm a print.":config.get("print_status"));
        LinearLayout station=LuceUi.card(this,page,"1  Station & delivery","Admin assigns the station. Windows controls printer, paper and Simulation.");
        route=new Spinner(this);route.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Method 1 - phone archive + local-first print","Method 2 - phone archive + cloud print"}));route.setSelection("cloud".equals(config.get("event_print_route"))?1:0);station.addView(route);
        add(station,"Prepare / refresh station (online)",()->work(this::prepare));
        add(station,"Test local network connection",()->work(()->{JSONObject setup=new JSONObject(config.secret("print_setup"));JSONObject r=new LanPrintApi(this,setup).call("/v1/info",null);say(r.getString("label")+" / "+(r.getBoolean("simulation")?"SIMULATION - no paper":"PHYSICAL PRINTING")+" / "+(r.getBoolean("paused")?"Paused":"Ready")+"\nProfile: "+r.getJSONArray("profiles").toString());}));
        LinearLayout choose=LuceUi.card(this,page,"2  Choose & confirm","Select one JPEG, then inspect the image, profile, guest association and copies. Nothing prints from opening this screen.");
        LuceUi.action(this,choose,"Select photo to preview",true,this::choose);
        LinearLayout queue=LuceUi.card(this,page,"Print queue","A sent job is not proof of paper output. Inspect unknown results at Windows before reprinting.");
        jobs=LuceUi.label(this,queue,"Loading queue...",14,false);
        add(queue,"Resume queued printing",this::resume);
        add(queue,"Pause phone print transfers",()->{config.prefs.edit().putBoolean("print_active",false).commit();stopService(new Intent(this,PrintService.class));say("Phone transfers paused. Already accepted station jobs may still print; pause the Windows station to stop execution.");});
        String fromGallery=getIntent().getStringExtra("gallery_job_id");
        if(fromGallery!=null&&!fromGallery.isEmpty()){
            io.execute(()->{
                try(QueueDb q=new QueueDb(this);android.database.Cursor c=q.getReadableDatabase().rawQuery(
                        "SELECT uri,state,is_test FROM jobs WHERE scope=? AND id=?",new String[]{config.get("scope"),fromGallery})){
                    if(!c.moveToFirst()||c.getInt(2)!=0||"retired_local".equals(c.getString(1)))throw new IllegalStateException("Photo is no longer available for a new print request.");
                    Uri photo=Uri.parse(c.getString(0));if(!"content".equals(photo.getScheme()))throw new IllegalStateException("Local photo URI unavailable; use cloud Staff Photo Desk.");
                    try(java.io.InputStream stream=getContentResolver().openInputStream(photo)){if(stream==null)throw new java.io.IOException("No local source");}
                    runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())selectProfile(photo,route.getSelectedItemPosition());});
                }catch(Exception e){say("Local original unavailable. Use the Cloud Staff Photo Desk to print this archived photo.");}
            });
        }
        LinearLayout help=LuceUi.disclosure(this,page,"Connection and paper help");
        LuceUi.label(this,help,"Method 1 uses reachable event LAN with eligible cloud fallback. Method 2 uses internet through Hostinger. A failed LAN check is not a Method 2 failure. Refresh authorized setup online before the event; local rights last at most 12 hours. Driver/cutter behavior still needs physical calibration.",14,false);
    }
    private TextView text(LinearLayout box,String t,int size){return LuceUi.label(this,box,t,size,size>=18);}
    private void add(LinearLayout box,String t,Runnable r){LuceUi.action(this,box,t,false,r);}
    private void say(String s){config.prefs.edit().putString("print_status",s).apply();runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()){info.setText(s);Toast.makeText(this,s,Toast.LENGTH_LONG).show();}});}
    private interface Task{void run()throws Exception;}private void work(Task task){io.execute(()->{try{task.run();}catch(CloudApi.Failure e){say("Print setup: "+e.code);}catch(LanPrintApi.Failure e){say("Station: "+e.code);}catch(Exception e){say(e instanceof IllegalStateException?e.getMessage():"Connection or file unavailable. Queue retained; check pairing, permissions and LAN.");}});}
    private void prepare()throws Exception{if(config.get("scope").isEmpty())throw new IllegalStateException("Pair this phone with the cloud first");try(CloudApi api=new CloudApi(this,config.get("base"),config.token(),config.cellular())){JSONObject cfg=api.call("/v1/device/print-config",null);if(cfg.optJSONObject("workflow")==null)throw new IllegalStateException("Upgrade cloud to H5.5 before preparing this client");String configured=cfg.getJSONObject("workflow").getString("print_route");config.prefs.edit().putString("event_print_route",configured).commit();runOnUiThread(()->route.setSelection("cloud".equals(configured)?1:0));if(!cfg.getJSONObject("permissions").optBoolean("print")||cfg.isNull("station"))throw new IllegalStateException("Ask Admin to assign this phone a Print Station and print permission");byte[] b=new byte[32];new SecureRandom().nextBytes(b);String secret=CloudApi.hex(b);JSONObject body=new JSONObject().put("station_id",cfg.getJSONObject("station").getString("id")).put("auth_hash",CloudApi.sha(secret.getBytes(java.nio.charset.StandardCharsets.UTF_8)));JSONObject setup=api.call("/v1/device/print-grant",body);setup.put("lan_secret",secret);setup.put("max_copies",cfg.getJSONObject("permissions").getInt("max_copies"));config.putSecret("print_setup",setup.toString());try(PrintQueue q=new PrintQueue(this)){q.resumeBlocked();}say("Prepared "+setup.getJSONObject("station").getString("label")+". Grant expires "+new java.util.Date(setup.getLong("expires"))+". Test LAN separately; assignment is not a connectivity test.");}}
    private void choose(){if(config.get("scope").isEmpty()){say("Pair a phone first");return;}Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/jpeg");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(i,51);}
    private void resume(){config.prefs.edit().putBoolean("print_active",true).putInt("print_mode",route.getSelectedItemPosition()).commit();try{startForegroundService(new Intent(this,PrintService.class));}catch(RuntimeException e){config.prefs.edit().putBoolean("print_active",false).commit();say("Android could not start printing transfer. Reopen the app; queue retained.");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=51||result!=RESULT_OK||data==null||data.getData()==null)return;final Uri uri=data.getData();final int selectedMode=route.getSelectedItemPosition();selectProfile(uri,selectedMode);}
    private void selectProfile(Uri uri,int mode){
        try{JSONObject setup=new JSONObject(config.secret("print_setup"));JSONArray list=setup.getJSONObject("station").getJSONArray("profiles");
            if(list.length()==0)throw new IllegalStateException("Publish a station profile and refresh station permissions first.");
            String[] labels=new String[list.length()];for(int i=0;i<labels.length;i++)labels[i]=list.getJSONObject(i).getString("label");
            new AlertDialog.Builder(this).setTitle("Select print profile").setItems(labels,(d,index)->{
                try{JSONObject selected=new JSONObject(list.getJSONObject(index).toString());work(()->preview(uri,mode,selected));}catch(JSONException e){say("Profile unavailable; refresh station.");}
            }).setNegativeButton("Cancel",null).show();
        }catch(Exception e){say("Prepare / refresh authorized station first. No job created.");}
    }
    private Bitmap layoutPreview(Bitmap source,JSONObject profile)throws Exception{
        String id=profile.getString("id");PrintProfilePolicy.validateSource(id,source.getWidth(),source.getHeight());
        if(!PrintProfilePolicy.isCp9550(id))return source;
        double pw=profile.getInt("width_hundredths"),ph=profile.getInt("height_hundredths"),scale=900.0/Math.max(pw,ph);
        int w=(int)Math.round(pw*scale),h=(int)Math.round(ph*scale);Bitmap out=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(out);canvas.drawColor(Color.WHITE);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);
        Bitmap rotated=null;
        try{for(double[] r:PrintProfilePolicy.plan(id,source.getWidth(),source.getHeight(),w,h)){
            Bitmap use=source;if(r[4]==1){if(rotated==null){Matrix m=new Matrix();m.setRotate(90);rotated=Bitmap.createBitmap(source,0,0,source.getWidth(),source.getHeight(),m,true);}use=rotated;}
            canvas.drawBitmap(use,null,new RectF((float)r[0],(float)r[1],(float)(r[0]+r[2]),(float)(r[1]+r[3])),paint);
        }}finally{if(rotated!=null&&rotated!=source)rotated.recycle();}
        source.recycle();return out;
    }
    private void preview(Uri uri,int selectedMode,JSONObject profile)throws Exception{JSONObject setup=new JSONObject(config.secret("print_setup"));if(setup.getLong("expires")<=System.currentTimeMillis())throw new IllegalStateException("Refresh station permission before creating another print");JSONObject st=setup.getJSONObject("station");JSONArray profiles=st.getJSONArray("profiles");boolean available=false;for(int i=0;i<profiles.length();i++){JSONObject x=profiles.getJSONObject(i);if(x.getString("id").equals(profile.getString("id"))&&x.getInt("revision")==profile.getInt("revision"))available=true;}if(!available)throw new IllegalStateException("Profile changed; refresh and reselect.");String scope=config.get("scope"),id=UUID.randomUUID().toString();String[] scopeParts=scope.split("\\|");if(scopeParts.length!=3)throw new IllegalStateException("Pairing identity missing");File directory=new File(getFilesDir(),"print-stage");if(!directory.exists()&&!directory.mkdirs())throw new IOException("No staging folder");long used=0;File[] files=directory.listFiles();if(files!=null)for(File f:files)used+=f.length();if(used>224L*1024*1024||directory.getUsableSpace()<1024L*1024*1024)throw new IllegalStateException("Phone print staging or free-space limit reached. Finish pending jobs first.");File target=new File(directory,id+".jpg");long count=0;MessageDigest hash=MessageDigest.getInstance("SHA-256");
        try(InputStream input=getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(target)){if(input==null)throw new IOException("Source missing");byte[] b=new byte[65536];int n;while((n=input.read(b))>=0){count+=n;if(count>32L*1024*1024)throw new IllegalStateException("Print JPEG must be no larger than 32 MiB");hash.update(b,0,n);out.write(b,0,n);}out.getFD().sync();}catch(Exception e){target.delete();throw e;}
        try{JpegStructure.validate(target);}catch(Exception e){target.delete();throw e;}
        BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(target.getPath(),bounds);if(count==0||!"image/jpeg".equals(bounds.outMimeType)||bounds.outWidth<=0||bounds.outHeight<=0||(long)bounds.outWidth*bounds.outHeight>60L*1024*1024){target.delete();throw new IllegalStateException("Valid JPEG up to 60 megapixels required");}
        BitmapFactory.Options decode=new BitmapFactory.Options();decode.inSampleSize=1;while(Math.max(bounds.outWidth,bounds.outHeight)/decode.inSampleSize>1000)decode.inSampleSize*=2;Bitmap raw=BitmapFactory.decodeFile(target.getPath(),decode);if(raw==null){target.delete();throw new IOException("Preview unavailable");}
        int orientation=new ExifInterface(target.getPath()).getAttributeInt(ExifInterface.TAG_ORIENTATION,1);Matrix matrix=new Matrix();switch(orientation){case 2:matrix.setScale(-1,1);break;case 3:matrix.setRotate(180);break;case 4:matrix.setRotate(180);matrix.postScale(-1,1);break;case 5:matrix.setRotate(90);matrix.postScale(-1,1);break;case 6:matrix.setRotate(90);break;case 7:matrix.setRotate(270);matrix.postScale(-1,1);break;case 8:matrix.setRotate(270);break;}Bitmap oriented=Bitmap.createBitmap(raw,0,0,raw.getWidth(),raw.getHeight(),matrix,true);if(oriented!=raw)raw.recycle();final Bitmap shown;try{shown=layoutPreview(oriented,profile);}catch(Exception e){if(!oriented.isRecycled())oriented.recycle();target.delete();throw new IllegalStateException(e.getMessage());}
        JSONObject spec=new JSONObject().put("id",id).put("event_id",scopeParts[1]).put("device_id",scopeParts[2]).put("station_id",st.getString("id")).put("sha256",CloudApi.hex(hash.digest())).put("bytes",count).put("profile_id",profile.getString("id")).put("profile_revision",profile.getInt("revision")).put("copies",1);
        runOnUiThread(()->{if(isFinishing()||isDestroyed()){shown.recycle();target.delete();return;}LinearLayout panel=new LinearLayout(this);panel.setPadding(16,16,16,16);panel.setOrientation(LinearLayout.VERTICAL);text(panel,st.optString("label")+"\n"+profile.optString("label")+" / contain / no crop\nPreview is nominal: driver margins/bleed and cutter must be calibrated. Strip profiles duplicate ONE finished strip; copies count sheet cycles.",15);ImageView image=new ImageView(this);image.setImageBitmap(shown);image.setAdjustViewBounds(true);image.setMaxHeight(700);panel.addView(image);NumberPicker copies=new NumberPicker(this);copies.setMinValue(1);copies.setMaxValue(setup.optInt("max_copies",1));panel.addView(copies);TextView quantityLabel=text(panel,PrintProfilePolicy.copyLabel(spec.optString("profile_id"),1),15);copies.setOnValueChangedListener((picker,oldValue,newValue)->quantityLabel.setText(PrintProfilePolicy.copyLabel(spec.optString("profile_id"),newValue)));final java.util.ArrayList<String> guestIds=new java.util.ArrayList<>();java.util.ArrayList<String> guestLabels=new java.util.ArrayList<>();guestIds.add(null);guestLabels.add("Staff-only / keep existing guest assignment");
        try(QueueDb q=new QueueDb(this)){JSONArray list=new WatchLedger(q).history(scope,0);for(int k=0;k<list.length();k++){JSONObject g=list.getJSONObject(k);if("open".equals(g.getString("state"))){guestIds.add(g.getString("id"));guestLabels.add(g.getString("label")+" / "+g.getString("kind"));}}}catch(Exception ignored){}
        Spinner guest=new Spinner(this);guest.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,guestLabels));text(panel,"Cloud archive guest assignment (not public release)",15);panel.addView(guest);
        final boolean[] keep={false};AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Confirm this exact photo for printing").setView(panel).setPositiveButton("Queue Print",(d,n)->{keep[0]=true;int quantity=copies.getValue();final String selectedGuest=guestIds.get(guest.getSelectedItemPosition());work(()->{boolean printSaved=false;try{if(!config.get("scope").equals(scope))throw new IllegalStateException("Event changed; reopen print preview");spec.put("copies",quantity);long waitUntil=System.currentTimeMillis()+20000;while(!TransferLane.enter()){if(System.currentTimeMillis()>waitUntil||!config.get("scope").equals(scope))throw new IllegalStateException("Transfer checkpoint unavailable. No print queued; retry preview after the current transfer.");Thread.sleep(100);}if(!config.get("scope").equals(scope)){TransferLane.leave();throw new IllegalStateException("Event changed; no print queued");}String archiveId;try{archiveId=ArchiveStaging.register(this,scope,target,spec,selectedGuest);}finally{TransferLane.leave();}try(PrintQueue q=new PrintQueue(this)){q.add(scope,spec,target.getPath(),new String[]{"hybrid","cloud"}[selectedMode],archiveId);printSaved=true;}say("Print and private archive queued separately. Cloud delivery may still be pending.");runOnUiThread(()->{config.prefs.edit().putString("test_only","").putBoolean("drain",config.get("folder").isEmpty()).commit();config.active(true);try{startForegroundService(new Intent(this,EventService.class));}catch(RuntimeException e){config.active(false);say("Print queued; open main screen and Resume photo archive.");}resume();});}finally{if(!printSaved)target.delete();}});}).setNegativeButton("Cancel",null).create();dialog.setOnDismissListener(d->{image.setImageDrawable(null);shown.recycle();if(!keep[0])target.delete();});dialog.show();});
    }
    @Override protected void onResume(){super.onResume();handler.post(refresh);}
    @Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
    @Override protected void onDestroy(){handler.removeCallbacks(refresh);io.shutdown();super.onDestroy();}
}
